// A posted journal entry. Insert-only: it never changes; corrections are reversals. The ETag is
// derived from the representation (it changes when the entry is reversed).
// Ref: #/components/schemas/JournalEntry
type JournalEntry struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Legal entity.
	LegalEntityID uuid.UUID `json:"legal_entity_id"`
	// Ledger.
	LedgerID uuid.UUID `json:"ledger_id"`
	// Whether the entry's ledger is the tenant's leading ledger. Analytics reads the leading ledger unless
	// a question names another (ADR-0044).
	LeadingLedger bool `json:"leading_ledger"`
	// Fiscal year.
	FiscalYear int32 `json:"fiscal_year"`
	// Fiscal period.
	FiscalPeriod int32 `json:"fiscal_period"`
	// Document type (SA general, KR supplier invoice, KZ payment...).
	DocumentType string `json:"document_type"`
	// Document number, unique per legal entity, document type and fiscal year.
	DocumentNumber string `json:"document_number"`
	// Document date.
	DocumentDate time.Time `json:"document_date"`
	// Posting date.
	PostingDate time.Time `json:"posting_date"`
	// Transaction currency.
	Currency string `json:"currency"`
	// Local currency.
	LocalCurrency string `json:"local_currency"`
	// Group currency.
	GroupCurrency string `json:"group_currency"`
	// Exchange rate from transaction to local currency.
	RateTcLc Decimal `json:"rate_tc_lc"`
	// Exchange rate from local to group currency.
	RateLcGc Decimal `json:"rate_lc_gc"`
	// External reference.
	Reference OptString `json:"reference"`
	// Header text.
	HeaderText OptString `json:"header_text"`
	// Context that produced the posting. Open enumeration: clients must accept and preserve values not
	// listed here; values may be added within /v1.
	SourceContext string `json:"source_context"`
	// Source document in that context.
	SourceDocumentID OptUUID `json:"source_document_id"`
	// Entry this one reverses.
	ReversalOfID OptUUID `json:"reversal_of_id"`
	// Entry that reversed this one, if any.
	ReversedByID OptUUID `json:"reversed_by_id"`
	// Lines; they balance to zero in every currency.
	Lines []JournalLine `json:"lines"`
	// Posting time.
	PostedAt time.Time `json:"posted_at"`
	// Principal that posted.
	PostedBy uuid.UUID `json:"posted_by"`
}

