// Merged schema.
// Ref: #/components/schemas/SupplierInvoice
type SupplierInvoice struct {
	// Identifier (UUIDv7).
	ID uuid.UUID `json:"id"`
	// Optimistic-lock version; equals the ETag. Increases by one on every change.
	Version int32 `json:"version"`
	// Creation time (UTC).
	CreatedAt time.Time `json:"created_at"`
	// Principal that created the resource.
	CreatedBy uuid.UUID `json:"created_by"`
	// Time of the last change (UTC).
	UpdatedAt time.Time `json:"updated_at"`
	// Principal that made the last change. Absent on resources whose table does not record it.
	UpdatedBy OptUUID `json:"updated_by"`
	// Document number.
	DocumentNumber string `json:"document_number"`
	// Legal entity.
	LegalEntityID uuid.UUID `json:"legal_entity_id"`
	// Supplier.
	SupplierID uuid.UUID `json:"supplier_id"`
	// The supplier's invoice number; unique per supplier (duplicates are refused).
	SupplierReference string `json:"supplier_reference"`
	// Invoice date.
	InvoiceDate time.Time `json:"invoice_date"`
	// Posting date; set at the latest by `:post`.
	PostingDate OptDate `json:"posting_date"`
	// Gross amount.
	GrossAmount Money `json:"gross_amount"`
	// Tax amount.
	TaxAmount Money `json:"tax_amount"`
	// Purchase order (PO-based invoices).
	PurchaseOrderID OptUUID `json:"purchase_order_id"`
	// What the document is, as SAP's invoice verification transactions: `invoice`, `credit_memo` (the
	// supplier credits what was invoiced: Dr supplier when posted), `subsequent_debit` or
	// `subsequent_credit` (a revaluation of order items already invoiced, without quantity). Amounts are
	// not negative whatever the kind, which gives the direction. Fixed once entered. Open enumeration:
	// clients must accept and preserve values not listed here; values may be added within /v1.
	Kind OptString `json:"kind"`
	// The posted invoice a credit memo or subsequent debit/credit corrects (of the same supplier, legal
	// entity and currency); never on an invoice.
	ReferenceInvoiceID OptUUID `json:"reference_invoice_id"`
	// Lifecycle status: `parked`, `on_hold` (`:hold`/`:release`), `posted` (`:post`), `cancelled`
	// (`:cancel`, unposted only), `reversed` (`:reverse`), or `rejected` when the approval request for an
	// invoice exception is rejected. Open enumeration: clients must accept and preserve values not listed
	// here; values may be added within /v1.
	Status string `json:"status"`
	// Why the invoice is on hold (status `on_hold`).
	HoldReason OptString `json:"hold_reason"`
	// How the invoice entered the system. Open enumeration: clients must accept and preserve values not
	// listed here; values may be added within /v1.
	Source string `json:"source"`
	// Journal entry posted for the invoice (statuses `posted` and `reversed`).
	JournalEntryID OptUUID `json:"journal_entry_id"`
	// The payment terms the invoice posted with (T36b): its order's term, else its supplier's in the legal
	// entity, counted from the invoice date; a correction naming an invoice has that invoice's. Absent
	// before posting, on a credit memo or subsequent credit naming no invoice (due at once, no discount),
	// and on invoices posted before terms were kept.
	PaymentTerms OptItemPaymentTerms `json:"payment_terms"`
	// Journal entry that reversed the posting (status `reversed`).
	ReversalEntryID OptUUID `json:"reversal_entry_id"`
	// Approval request for an invoice exception, if any.
	WorkflowRequestID OptUUID `json:"workflow_request_id"`
	// Items.
	Items []SupplierInvoiceItem `json:"items"`
	// Custom fields.
	Extensions Extensions `json:"extensions"`
	// Expanded references.
	Expanded OptExpanded `json:"expanded"`
}

